---FreshUI
---@param geneData table @{ geneId:integer, skillId:integer, additions:integer }
function CatHousDataDetailsNode:FreshUI(geneData)
    local geneId      = geneData.geneId
    -- geneId = 4101
    ---@type CatHouseCatDataVo
    local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
    -- if not isNull(self.titleBgSwitch) then
    --     self.titleBgSwitch.Status = checkNumber(catGeneData.kind)
    -- end

    self:FreshTitleNode(catGeneData)
    ---------------------
    --- 刷新标题
    -- self.TitleText.text = catGeneData.name
    self:FreshDataType(catGeneData)

    --- 1基础、2组合、3变异、4部件
    local kind        = catGeneData.kind
    if kind == ScreenCatDataType.Basic then
        self:FreshBasicKindUI(catGeneData)

    elseif kind == ScreenCatDataType.Combination then
        self:FreshCombinationKindUI(catGeneData)
        
    elseif kind == ScreenCatDataType.Variation then
        self:FreshVariationKindUI(catGeneData)
        
    elseif kind == ScreenCatDataType.Part then
        self:FreshPartKindUI(catGeneData, geneData)

    end
end

function CatHousDataDetailsNode:FreshTitleNode(catGeneData)
    CommonTipsBoard.RefreshTitleNode(self, catGeneData.name, nil, TitleBgColor[checkNumber(catGeneData.kind)], nil, true)
end

function CatHousDataDetailsNode:FreshDataType(catGeneData)
    ------------------------
    --- 准备数据
    local kind     = catGeneData.kind 
    
    local t        = {}
    table.insert(t, KindTypeName[kind])
    if kind ~= ScreenCatDataType.Variation then
        local place    = catGeneData.place 
        table.insert(t, PlaceTypeName[place])

    end

    ------------------------
    --- 刷新UI
    local parent   = self.DataType.gameObject
    local child = self.TypeNode.gameObject

    for i, name in ipairs(t) do
        local go        = parent:AddChild(child)
        
        local Text = go.transform:Find("Text")
        CfUtils.FillText(Text, name)

        KTool.SetActive(go.gameObject, true)
    end
    KTool.SetActive(parent, true)
end

function CatHousDataDetailsNode:FreshBasicKindUI(catGeneData)
    local parent = self.SynthesisRemind.gameObject
    local child  = self.DescribeNode.gameObject
    KTool.SetActive(parent, true)

    local geneId = catGeneData.id
    --- 填充kind为2
    ---@type BaseSetting
    local setting     = CfUtils.GetCf(AutoIds.IdSetting1910, "CatHouseHeritableVo")
    ---@type CatHouseHeritableVo[]
    local heritableVos = setting:GetAll()
    local formulaKey2CombinationGeneId = {}
    
    for i, heritableVo in ipairs(heritableVos) do
        local formula = heritableVo.formula
        for _, formulaGeneId in ipairs(formula) do
            --- 先找和当前基础基因一致的基因
            if checkNumber(formulaGeneId) == geneId then
                --- 过滤当前基础基因一致的基因  并 更新UI
                for _, basicGeneId in ipairs(formula) do
                    if checkNumber(basicGeneId) ~= geneId then
                        local go        = parent:AddChild(child)
                        
                        local transform = go.transform
                        local dataNode  = transform:Find("CatHouseBtnDataNode")
                        self:FreshGeneDataNode(dataNode, basicGeneId)
                        
                        local dataNode2 = transform:Find("CatHouseBtnDataNode2")
                        self:FreshGeneDataNode(dataNode2, heritableVo.id)
                        
                        KTool.SetActive(go.gameObject, true)
                    end
                end
                break
               
            end
        end
    end

end

function CatHousDataDetailsNode:FreshCombinationKindUI(catGeneData)
    ------------------------
    --- 刷新猫种族
    self:FreshCatRace(catGeneData)
    
    ------------------------
    --- 刷新合成所需数据
    ---@type CatHouseHeritableVo
    local heritableVo   = CfUtils.GetCfVo(AutoIds.IdSetting1910, "CatHouseHeritableVo", catGeneData.id)
    local formula = heritableVo.formula

    self:FreshCombinationPartByFormula(formula)
    

end

function CatHousDataDetailsNode:FreshVariationKindUI(catGeneData)
    ------------------------
    --- 刷新猫种族
    self:FreshCatRace(catGeneData)

    ------------------------
    --- 刷新合成所需数据
    ---@type CatHouseHeritableVo
    local heritableVo   = CfUtils.GetCfVo(AutoIds.IdSetting1911, "CatHouseHeritableVo", catGeneData.id)
    self:FreshCombinationPartByFormula(heritableVo.formula)

    ------------------------
    --- 刷新合卡技
    
    local skillIdList  = catGeneData.skillIdList
    local questConfMgr = QuestConfMgr:GetInstance()
    local parent       = self.CardSkill.gameObject
    local child        = self.Details.gameObject
    KTool.SetActive(parent.gameObject, true)
    KTool.SetActive(child.gameObject, false)

    for i, skillId in ipairs(skillIdList) do
        ---@type UnitSkillVo
        local vo = questConfMgr:GetMergeSkillVo(skillId)
        local go = parent:AddChild(child)
        local transform = go.transform
        local ImgIcon   = transform:Find("ImgIcon") 
        CfUtils.FillImage(ImgIcon, vo.photoPath)

        local TextName  = transform:Find("TextName") 
        local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(skillId, 1)
        CfUtils.FillCfText(TextName, skillVo.skillName)

        local t = {}
        if vo.typeOne ~= "" then
            table.insert(t, { vo.typeOne, vo.typeOneColor })
        end
        if vo.typeTwo ~= "" then
            table.insert(t, { vo.typeTwo, vo.typeTwoColor })
        end
        for index, config in ipairs(t) do
            local name, colorStatus = SafeUnpack(config)
            local node = go.gameObject:AddChild(self.SkillTypeNode.gameObject)
            local nodeTransform = node.transform
            CfUtils.FillText(nodeTransform:Find("Text"), name)
            CfUtils.SetUISwitchImage(nodeTransform:Find("ImgBg"), colorStatus)

            KTool.SetActive(node.gameObject, true)
            
        end
        KTool.SetActive(go.gameObject, true)
        
    end

end

--- FreshPartKindUI
--- 刷新部件UI
---@param catGeneData CatHouseCatDataVo
function CatHousDataDetailsNode:FreshPartKindUI(catGeneData, geneData)
    KTool.SetActive(self.DataAddition.gameObject, true)
    local parent       = self.DataAdditionContent.gameObject
    local child        = self.CatAttributeNode.gameObject

    local catSkillIdList     = catGeneData.catSkillIdList
    local variationKindList  = catGeneData.variationKindList
    local variationNumList   = catGeneData.variationNumList
    local cardConfMgr        = CardConfMgr:GetInstance()

    if catSkillIdList then
        self.DataAdditionTxtTitle.Status = 2
        local catSkillId = geneData.skillId
        local go = parent:AddChild(child)
        ---@type CatHouseInteractionAttributeNode
        local scr = CfUtils.GetLuaScr(go, AttributeNodeEnvPath)
        if scr then
            ---@type CatHouseCatSkillVo
            local skillVo = CatHouseMgr:GetInstance():GetCatSkillByRefId(catSkillId)
            if skillVo then
                ---@type CatHouseCatAttributeVo
                local attributeVo = CatHouseMgr:GetInstance():GetCatAttributeByRefId(skillVo.attributeId)
                local desc = checkNumber(geneData.additions) > 0 and string.gsub(skillVo.desc, "_target_num_", geneData.additions) or skillVo.handbookDesc
                scr:FreshCatAttribute(desc, attributeVo.picture)
            end  
        end
        KTool.SetActive(go.gameObject, true)

    elseif variationKindList and variationNumList then
        self.DataAdditionTxtTitle.Status = 1
        for i, attrAddId in ipairs(variationKindList) do
            local go = parent:AddChild(child)
            ---@type CatHouseInteractionAttributeNode
            local scr = CfUtils.GetLuaScr(go, AttributeNodeEnvPath)
            if scr then
                ---属性加城与技能数据处理
                local attributeVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(attrAddId)
                if attributeVo then
                    scr:FreshBaseUI({ name = attributeVo.name, picture = attributeVo.icon }, i)
                    scr:FreshAttrValue({ num = '+' .. attribute_format(attributeVo.isConversion, variationNumList[i]) })
                end  
            end
            KTool.SetActive(go.gameObject, true)
    
        end
    end
end

function CatHousDataDetailsNode:FreshCombinationPartByFormula(formula)
    KTool.SetActive(self.SynthesisNeed.gameObject, true)
    local parent = self.SynthesisNeed.gameObject
    local child  = self.CatHouseBtnDataNode.gameObject
    for i, geneId in ipairs(formula) do
        local go = parent:AddChild(child)
        self:FreshGeneDataNode(go, geneId)
        KTool.SetActive(go.gameObject, true)
    end
end

function CatHousDataDetailsNode:FreshCatRace(catGeneData)
    KTool.SetActive(self.Race.gameObject, true)
    local catIdList = catGeneData.catIdList
    local t = {}
    for i, v in ipairs(catIdList) do
        ---@type CatHouseCatVo
        local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", v)
        table.insert(t, catHouseCatVo.name)
    end
    self.RaceText2.text  = table.concat(t, " ")
end

function CatHousDataDetailsNode:FreshGeneDataNode(dataNode, geneId)
    ---@type CatHouseDataNode
    local nodeEnv = CfUtils.GetLuaScr(dataNode, CellEnvPath)
    if not isNull(nodeEnv) then
        nodeEnv:FreshChild({geneId = geneId})
    end
end

